              <p className="text-base font-bold mt-0.5" style={{ color: 'var(--text-primary)' }}>{user.name}님, 안녕하세요!</p>
            </div>
            <div className="text-right">
              <p className="text-2xl font-bold tabular-nums tracking-tight" style={{ color: 'var(--text-primary)' }}>
