              <div>
                <p className="text-[11px] leading-relaxed font-medium" style={{ color: 'var(--text-primary)' }}>
                  {mealMenu.join(', ')}
                </p>
                {mealKcal && (
                  <p className="text-[10px] font-bold text-right mt-2" style={{ color: 'var(--accent-orange)' }}>
                    {mealKcal}
