const widgetEnd = lines.findIndex(l => l.includes('        {/* 메모 보드 (포스트잇) */}'));

if (widgetStart !== -1 && widgetEnd !== -1) {
  const replacement = [
    '        {/* 파일/폴더 즐겨찾기 */}',
